package main

import (
	"bufio"
	"fmt"
	"os"
	"strconv"
	"strings"

	"github.com/shopspring/decimal"
)

type DiscRec struct {
	DrItem  string
	DrPrice decimal.Decimal
	DrPct   int64
}

var WsEofFlag string = "N"
var WsDiscount decimal.Decimal = decimal.New(0, 0)
var WsNet decimal.Decimal = decimal.New(0, 0)
var WsTotalNet decimal.Decimal = decimal.New(0, 0)
var WsCount int64 = 0
var WsPriceEd string
var WsDiscEd string
var WsNetEd string
var WsTotalEd string

var discRec DiscRec
var discFile *os.File
var discScanner *bufio.Scanner

func pow10Int64(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func applyModAbs(abs decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	// abs >=0, already scaled correctly
	scaledDec := abs.Truncate(scale).Shift(scale)
	scaledInt := scaledDec.Truncate(0).IntPart()
	mod := pow10Int64(intDigits + int(scale))
	eff := scaledInt % mod
	return decimal.New(eff, -scale)
}

func storeRounded(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	rounded := v.Round(scale)
	isNeg := rounded.Sign() < 0
	abs := rounded.Abs()
	resAbs := applyModAbs(abs, intDigits, scale)
	if isNeg {
		resAbs = resAbs.Neg()
	}
	return resAbs
}

func storeTruncated(v decimal.Decimal, intDigits int, scale int32) decimal.Decimal {
	truncated := v.Truncate(scale)
	isNeg := truncated.Sign() < 0
	abs := truncated.Abs()
	resAbs := applyModAbs(abs, intDigits, scale)
	if isNeg {
		resAbs = resAbs.Neg()
	}
	return resAbs
}

func storeInt(v int64, width int) int64 {
	mod := pow10Int64(width)
	if v >= 0 {
		return v % mod
	}
	return -((-v) % mod)
}

func parsePrice(s string) decimal.Decimal {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return decimal.Zero
	}
	cleaned := strings.ReplaceAll(trimmed, " ", "")
	if cleaned == "" {
		return decimal.Zero
	}
	d, err := decimal.NewFromString(cleaned)
	if err != nil {
		fmt.Fprintln(os.Stderr, "parse price error:", err)
		os.Exit(1)
	}
	return d.Shift(-2)
}

func parsePct(s string) int64 {
	trimmed := strings.TrimSpace(s)
	if trimmed == "" {
		return 0
	}
	cleaned := strings.ReplaceAll(trimmed, " ", "")
	if cleaned == "" {
		return 0
	}
	v, err := strconv.ParseInt(cleaned, 10, 64)
	if err != nil {
		fmt.Fprintln(os.Stderr, "parse pct error:", err)
		os.Exit(1)
	}
	return v
}

func formatUneditedInt(v int64, width int) string {
	mod := pow10Int64(width)
	eff := v % mod
	if eff < 0 {
		eff = -eff
	}
	return fmt.Sprintf("%0*d", width, eff)
}

func formatEdited(val decimal.Decimal, pict string) string {
	dotIdx := strings.Index(pict, ".")
	var intPict, fracPict string
	var scale int
	if dotIdx == -1 {
		intPict = pict
		fracPict = ""
		scale = 0
	} else {
		intPict = pict[:dotIdx]
		fracPict = pict[dotIdx+1:]
		scale = len(fracPict)
	}
	intCap := 0
	for _, ch := range intPict {
		if ch == 'Z' || ch == '9' {
			intCap++
		}
	}
	isNeg := val.Sign() < 0
	abs := val.Abs()
	absTrunc := abs.Truncate(int32(scale))
	scaledDec := absTrunc.Shift(int32(scale))
	scaledInt := scaledDec.Truncate(0).IntPart()
	mod := pow10Int64(intCap + scale)
	effScaled := scaledInt % mod
	if effScaled < 0 {
		effScaled = -effScaled
	}
	var intPart, fracPart int64
	if scale > 0 {
		powScale := pow10Int64(scale)
		intPart = effScaled / powScale
		fracPart = effScaled % powScale
	} else {
		intPart = effScaled
		fracPart = 0
	}
	intDigitsStr := ""
	if intCap > 0 {
		intDigitsStr = fmt.Sprintf("%0*d", intCap, intPart)
	}
	outInt := make([]rune, len(intPict))
	suppressed := true
	digitIdx := 0
	for i, ch := range intPict {
		if ch == 'Z' || ch == '9' {
			d := intDigitsStr[digitIdx]
			if ch == 'Z' {
				if suppressed && d == '0' {
					outInt[i] = ' '
				} else {
					outInt[i] = rune(d)
					suppressed = false
				}
			} else {
				outInt[i] = rune(d)
				suppressed = false
			}
			digitIdx++
		} else if ch == ',' {
			if suppressed {
				outInt[i] = ' '
			} else {
				outInt[i] = ','
			}
		} else {
			outInt[i] = ch
		}
	}
	intFormatted := string(outInt)
	var result string
	if dotIdx != -1 {
		fracFormatted := fmt.Sprintf("%0*d", scale, fracPart)
		result = intFormatted + "." + fracFormatted
	} else {
		result = intFormatted
	}
	if isNeg && len(result) > 0 {
		result = "-" + result[1:]
	}
	return result
}

func InputDone() bool {
	return WsEofFlag == "Y"
}

func ReadPara() {
	if discScanner.Scan() {
		line := discScanner.Text()
		if len(line) < 15 {
			line = line + strings.Repeat(" ", 15-len(line))
		} else if len(line) > 15 {
			line = line[:15]
		}
		drItemRaw := line[0:6]
		discRec.DrItem = drItemRaw
		priceRaw := line[6:13]
		discRec.DrPrice = parsePrice(priceRaw)
		pctRaw := line[13:15]
		discRec.DrPct = parsePct(pctRaw)
	} else {
		if err := discScanner.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		WsEofFlag = "Y"
	}
}

func ProcessPara() {
	v := discRec.DrPrice.Mul(decimal.NewFromInt(discRec.DrPct)).Shift(-2)
	WsDiscount = storeRounded(v, 5, 2)
	v2 := discRec.DrPrice.Sub(WsDiscount)
	WsNet = storeTruncated(v2, 5, 2)
	sumTotal := WsTotalNet.Add(WsNet)
	WsTotalNet = storeTruncated(sumTotal, 8, 2)
	WsCount = storeInt(WsCount+1, 3)
	WsPriceEd = formatEdited(discRec.DrPrice, "ZZ,ZZ9.99")
	WsDiscEd = formatEdited(WsDiscount, "ZZ,ZZ9.99")
	WsNetEd = formatEdited(WsNet, "ZZ,ZZ9.99")
	pctStr := formatUneditedInt(discRec.DrPct, 2)
	line := discRec.DrItem + " " + WsPriceEd + " " + pctStr + "% " + WsDiscEd + " " + WsNetEd
	fmt.Fprintln(os.Stdout, line)
	ReadPara()
}

func SummaryPara() {
	WsTotalEd = formatEdited(WsTotalNet, "ZZ,ZZZ,ZZ9.99")
	countStr := formatUneditedInt(WsCount, 3)
	line := "ITEMS: " + countStr + " NET TOTAL: " + WsTotalEd
	fmt.Fprintln(os.Stdout, line)
}

func MainPara() {
	var err error
	discFile, err = os.Open("input.dat")
	if err != nil {
		fmt.Fprintln(os.Stderr, err)
		os.Exit(1)
	}
	discScanner = bufio.NewScanner(discFile)
	ReadPara()
	for !InputDone() {
		ProcessPara()
	}
	discFile.Close()
	SummaryPara()
}

func main() {
	MainPara()
}
